@Controller
public class OrdersController {
    private final OrderService orders;
    public OrdersController(OrderService orders) { this.orders = orders; }

    @GetMapping("/orders")
    public String list(Model model, Principal user) {
        model.addAttribute("orders", orders.list(user.getName()));   // domain logic
        return "orders";                                             // view name
    }
}
